export const imagerySamples=definition.map(spec=>{
    const textSlide=(t,i)=>({slideNumber:i,slideType:'text-visual',title:t[0],subtitle:'',objective:t[2],layoutId:'text-visual-split',visualRequirement:{role:'foreground',kind:'photo',required:true,description:`${t[1]}; representative stock illustration, not the actual facility of any named company.`,searchQuery:t[1],altText:t[1]},content:{visualContent:{text:t[2],visual:{type:'photo',description:t[1],searchQuery:t[1]}}}});
    const [cover,...others]=spec.topics;
    const processes={healthcare:[['Collect evidence','Identify the intended clinical task.'],['Validate','Test performance in the target setting.'],['Monitor','Track errors and review clinical use.']],marine:[['Map habitats','Identify important habitats and threats.'],['Reduce pressures','Apply appropriate conservation measures.'],['Monitor outcomes','Evaluate ecological changes over time.']],business:[['Research demand','Test customer needs and market access.'],['Pilot a launch','Evaluate delivery and operating costs.'],['Review economics','Use evidence to decide whether to scale.']],energy:[['Assess resources','Evaluate local energy potential.'],['Design integration','Plan grid access and flexibility.'],['Monitor performance','Review output and environmental effects.']],pharmaceutical:[['Define the process','Document materials and control needs.'],['Validate operations','Assess evidence against defined criteria.'],['Maintain oversight','Monitor records, deviations and quality.']]};
    const relationshipTitles={healthcare:'Clinical Evidence and Review',marine:'Conservation Evidence and Action',business:'Market Evidence and Expansion',energy:'Energy Planning and Evaluation',pharmaceutical:'Manufacturing Evidence and Oversight'};
    const title={slideNumber:1,slideType:'title',title:spec.title,subtitle:'Applications, systems and responsible decisions',objective:cover[2],visualRequirement:{role:'background',kind:'photo',required:true,description:cover[1],searchQuery:cover[1],altText:cover[1]},content:{titleContent:{title:spec.title,subtitle:'Applications, systems and responsible decisions',supportingText:'Illustrative photography with source and license records'}}};
    const slides=[title,...others.slice(0,4).map((t,i)=>textSlide(t,i+2)),
        {slideNumber:6,slideType:'process',title:'A Structured Decision Process',subtitle:'A proposed decision framework',objective:'Connect evidence to action and review',content:{process:{steps:[{stepNumber:1,title:'Understand',description:'Identify objectives, constraints and evidence.'},{stepNumber:2,title:'Act',description:'Implement a justified and monitored approach.'},{stepNumber:3,title:'Review',description:'Evaluate outcomes and revise the approach.'}]}},visualRequirement:{role:'none',kind:'none',required:false,description:'',searchQuery:'',altText:''}},
        {slideNumber:7,slideType:'relationship',title:'Evidence, Decisions and Outcomes',subtitle:'A conceptual relationship, not a measured causal model',objective:'Distinguish evidence, action and evaluation',content:{relationship:{nodes:[{id:'e',label:'Evidence',description:'Available observations'},{id:'d',label:'Decision',description:'A justified course of action'},{id:'o',label:'Review',description:'Evaluation of outcomes'}],relationships:[{from:'e',to:'d',label:'Informs'},{from:'d',to:'o',label:'Requires'}]}},visualRequirement:{role:'foreground',kind:'diagram',required:true,description:'Conceptual evidence and review relationship',searchQuery:'',altText:'Evidence informs decisions requiring review'}},
        textSlide(others[4],8)];
    slides[5].title={healthcare:'A Clinical Adoption Workflow',marine:'A Conservation Action Cycle',business:'A Staged Expansion Decision',energy:'Planning Renewable Integration',pharmaceutical:'Controlled Manufacturing Operations'}[spec.name];slides[5].content.process.steps=processes[spec.name].map(([title,description],i)=>({stepNumber:i+1,title,description}));
    slides[6].title=relationshipTitles[spec.name];slides[6].content.relationship.nodes=[{id:'e',label:'Evidence',description:'Relevant observations'},{id:'d',label:'Action',description:processes[spec.name][1][0]},{id:'o',label:'Review',description:processes[spec.name][2][0]}];
    slides[7].slideType='summary';slides[7].content={summary:{statement:others[4][2],points:['Match decisions to evidence.','Monitor outcomes and limitations.']}};
    return {...spec,context:{audience:'Professional learning audience',designPreferences:{theme:spec.theme,variant:spec.variant,...(['healthcare','pharmaceutical'].includes(spec.name)?{imageFocalPoints:{5:{x:.5,y:.32}}}:{}),...(spec.name==='marine'?{noImageSlideNumbers:[8]}:{})}},presentation:{outputType:'presentation',title:spec.title,subtitle:title.subtitle,strategyId:'general-presentation',slides}};
});
